export const simannealOptimizeSubset = East.function([FloatType], BooleanType, ($, budget) => {
  const task_costs = $.let(
    East.Vector.fromArray(East.value([5, 12, 3, 8, 15, 7], ArrayType(FloatType))),
  );
  const task_benefits = $.let(
    East.Vector.fromArray(East.value([4, 10, 2, 7, 13, 6], ArrayType(FloatType))),
  );
  const energy = $.const(
    East.function([VectorType(BooleanType)], FloatType, ($, selection) => {
      const total_cost = $.let(0);
      const total_benefit = $.let(0);
      $.for(East.Array.range(East.value(0n), 6n, 1n), ($, i, _7, label) => {
        $.if(selection.get(i), ($) => {
          $.assign(total_cost, total_cost.add(task_costs.get(i)));
          $.assign(total_benefit, total_benefit.add(task_benefits.get(i)));
        });
      });
      const penalty = $.let(
        East.greater(total_cost, budget).ifElse(
          ($) => total_cost.subtract(budget).multiply(100),
          ($) => 0,
        ),
      );
      $.return(total_benefit.negate().add(penalty));
    }),
  );
  const initial = $.let(
    East.Vector.fromArray(
      East.value([false, false, false, false, false, false], ArrayType(BooleanType)),
    ),
  );
