// Generated by east-node transpile — East IR printed as the East.function
// builder surface. Rebuilding this module yields the same IR (normalized).
import { East, some, none, NullType, BooleanType, IntegerType, FloatType, ArrayType, StructType, VariantType, OptionType } from "@elaraai/east";
import { Sklearn } from "@elaraai/east-py-datascience";

export const sklearnGmm = East.function([], BooleanType, ($) => {
  const X = $.let(
    East.Matrix.fromArray(
      East.value(
        [[1, 1], [1.1, 1.1], [1.2, 0.9], [0.9, 1.2], [5, 5], [5.1, 5.1], [5.2, 4.9], [4.9, 5.2]],
        ArrayType(ArrayType(FloatType)),
      ),
    ),
  );
  const config = $.let(
    {
      n_components: some(2n),
      covariance_type: none,
      max_iter: some(100n),
      n_init: some(1n),
      tol: none,
      reg_covar: none,
      random_state: some(42n),
    },
    StructType({
      n_components: OptionType(IntegerType),
      covariance_type: OptionType(VariantType({
        diag: NullType,
        full: NullType,
        spherical: NullType,
        tied: NullType,
      })),
      max_iter: OptionType(IntegerType),
      n_init: OptionType(IntegerType),
      tol: OptionType(FloatType),
      reg_covar: OptionType(FloatType),
      random_state: OptionType(IntegerType),
    }),
  );
  const model = $.let(Sklearn.gmmFit(X, config));
  const labels = $.let(Sklearn.gmmPredict(model, X));
  const proba = $.let(Sklearn.gmmPredictProba(model, X));
  return East.equal(labels.length(), 8n).ifElse(
    ($) => East.equal(proba.rows(), 8n),
    ($) => false,
  ).ifElse(($) => East.equal(proba.cols(), 2n), ($) => false);
});

