# builder surface. Rebuilding this module yields the same IR (normalized).
from east import East, IntegerType, FloatType, ArrayType, StructType, VectorType, MatrixType

sklearn_overlap = East.platform(
    'sklearn_overlap',
    [
        MatrixType(FloatType),
        ArrayType(MatrixType(FloatType)),
        ArrayType(MatrixType(FloatType)),
        StructType([('cat_indices', VectorType(IntegerType))]),
    ],
    StructType([
        ('X_filtered', ArrayType(MatrixType(FloatType))),
        ('Y_filtered', ArrayType(MatrixType(FloatType))),
        ('rejected_counts', VectorType(IntegerType)),
        ('known_categories', ArrayType(VectorType(IntegerType))),
    ]),
)

@East.function([], IntegerType, cse=False)
def sklearnOverlap(b):
    X_ref = b.let(
        East.Matrix.from_array(
            East.new_array(
                ArrayType(FloatType),
                [[0.0, 10.0], [1.0, 20.0], [0.0, 30.0], [1.0, 40.0]],
            ),
        ),
    )
    X_prod = b.let(
        East.Matrix.from_array(
            East.new_array(ArrayType(FloatType), [[0.0, 11.0], [3.0, 22.0], [1.0, 33.0]]),
        ),
    )
    Y_prod = b.let(
        East.Matrix.from_array(East.new_array(ArrayType(FloatType), [[1.0], [2.0], [3.0]])),
    )
    result = b.let(
        sklearn_overlap(
            X_ref,
            [X_prod],
            [Y_prod],
            {'cat_indices': East.new_array(IntegerType, [0]).to_vector()},
        ),
    )
    return result.X_filtered.get(0).rows()

