                                caretColor={color.caret}
                                connectorColor={color.connector}
                                defaultExpandedValue={expanded}
                                selectionMode="multiple"
                                onSelectionChange={onSelectionChange}
                                onExpandedChange={onExpandedChange}
                                onFocusChange={onFocusChange}
                                nodes={tree.nodes}
