                const onDate    = $.const(East.function([DateTimeType], NullType, ($, next) => { $(dateBind.write(next)); }));
                const onFocus   = $.const(East.function([], NullType, $ => {
                    const current = $.let(focusCountBind.read());
                    $(focusCountBind.write(current.add(1n)));
